css:
.tn-header {
  margin-bottom: 1.0mm;
}
.tn-title {
  font-weight: 700;
  font-size: 8pt;
  margin: 0;
}
.tn-meta {
  color: #555;
  font-size: 5.8pt;
  margin-top: 0.2mm;
}
.tn-meta .sep {
  color: #aaa;
  padding: 0 0.6mm;
}
.tn-bemerkung {
  margin-top: 0.6mm;
  font-size: 5.8pt;
  color: #333;
  font-style: italic;
}
.tn-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 6.35pt;
  line-height: 1.35;
  table-layout: fixed;
}
.tn-table th {
  text-align: left;
  font-size: 5.2pt;
  color: #555;
  text-transform: uppercase;
  letter-spacing: 0;
  border-bottom: 0.3pt solid #333;
  padding: 0.5mm 0.5mm !important;
  font-weight: 600;
}
.tn-table td {
  padding: 1.2mm 0.5mm !important;
  vertical-align: top !important;
  border-bottom: 0.25pt solid #ccc;
}
.tn-table tr.eintrag-row {
  break-inside: avoid;
  page-break-inside: avoid;
}
.tn-wohnung-id {
  font-weight: 700;
  font-size: 6.7pt;
  text-align: right;
  color: #111;
  white-space: nowrap;
  padding-right: 0.7mm;
}
.tn-wohnung {
  font-weight: 600;
  white-space: nowrap;
  font-size: 6.35pt;
  overflow: hidden;
}
.tn-imm {
  color: #777;
  font-size: 5.25pt;
  font-weight: 400;
  margin-left: 0.45mm;
}
.tn-people-cell {
  overflow-wrap: anywhere;
}
.tn-contact-row {
  display: grid;
  grid-template-columns: 40% 60%;
  min-height: 2.8mm;
  line-height: 1.35;
}
.tn-contact-name {
  padding-right: 0.5mm;
}
.tn-mieter {
  font-weight: 500;
}
.tn-rolle {
  color: #777;
  font-size: 5.25pt;
  margin-left: 0.25mm;
}
.tn-empty {
  color: #bbb;
}
.tn-section td {
  background: #eee;
  font-weight: 700;
  font-size: 6.8pt;
  padding: 1.4mm 0.7mm 0.7mm !important;
  border-top: 0.4pt solid #333 !important;
  border-bottom: 0.4pt solid #333 !important;
  letter-spacing: 0.2pt;
  text-transform: uppercase;
  break-after: avoid;
  page-break-after: avoid;
}
.print-hide, .action-banner {
  display: none !important;
}
.tn-email { overflow-wrap: anywhere; }

html:
{%- set groups = doc.get_grouped_eintraege() -%}
{%- set anzahl_eintraege = doc.eintraege|length -%}
{%- set show_sections = doc.nach_gebaeudeteil_sortieren -%}
{%- set teil_labels = {"VH": "Vorderhaus", "SF": "Seitenflügel", "HH": "Hinterhaus"} -%}
{%- set sec_ns = namespace(last_teil="__UNSET__") -%}

<div class="tn-header">
  <h1 class="tn-title">{{ doc.titel or _("E-Mail-Adressen Mieter") }}</h1>
  <div class="tn-meta">
    {{ _("Stichtag") }}: {{ frappe.utils.formatdate(doc.stichtag) }}
    {%- if doc.immobilie %}
      <span class="sep">·</span>{{ _("Immobilie") }}: {{ (frappe.db.get_value('Immobilie', doc.immobilie, 'adresse_titel') or doc.immobilie) if doc.immobilie else '' }}
    {%- endif %}
    <span class="sep">·</span>{{ _("Einträge") }}: {{ anzahl_eintraege }}
  </div>
  {%- if doc.bemerkung %}
    <div class="tn-bemerkung">{{ doc.bemerkung }}</div>
  {%- endif %}
</div>

{%- if not groups %}
  <p class="tn-empty">{{ _('Keine Einträge vorhanden. Bitte im Formular auf "Einträge laden" klicken.') }}</p>
{%- else %}
  <table class="tn-table">
    <thead>
      <tr>
        <th style="width: 6%; text-align: right;">{{ _("ID") }}</th>
        <th style="width: 24%">{{ _("Wohnung") }}</th>
        <th style="width: 28%">{{ _("Mieter") }}</th>
        <th style="width: 42%">{{ _("E-Mail") }}</th>
      </tr>
    </thead>
    <tbody>
      {%- for grp in groups %}
        {%- if show_sections and grp.gebaeudeteil != sec_ns.last_teil %}
          <tr class="tn-section"><td colspan="4">{{ teil_labels.get(grp.gebaeudeteil, grp.gebaeudeteil) or _("Ohne Gebäudeteil") }}</td></tr>
          {%- set sec_ns.last_teil = grp.gebaeudeteil -%}
        {%- endif %}
        <tr class="eintrag-row">
          <td class="tn-wohnung-id">{{ grp.wohnung_id if grp.wohnung_id is not none else '' }}</td>
          <td class="tn-wohnung">
            {{ grp.wohnung_label or grp.wohnung }}
          </td>
          <td class="tn-people-cell" colspan="2">
            {%- for m in grp.mieter -%}
              <div class="tn-contact-row">
                <div class="tn-contact-name">
                  <span class="tn-mieter">{{ m.name }}</span>
                  {%- if m.rolle and m.rolle != 'Hauptmieter' %}<span class="tn-rolle">({{ m.rolle }})</span>{% endif -%}
                </div>
                <div class="tn-email">
                  {%- if m.email %}{{ m.email }}{% else %}<span class="tn-empty">—</span>{% endif -%}
                </div>
              </div>
            {%- endfor %}
          </td>
        </tr>
      {%- endfor %}
    </tbody>
  </table>
{%- endif %}
